package com.bank.loadtest.service;

import java.util.concurrent.atomic.AtomicLong;

// Simulated payments endpoint: fast baseline, periodic long stall (like a GC pause).
public class PaymentService {
    private static final long BASELINE_US = 2_000;     // 2 ms normal
    private static final long STALL_US     = 200_000;   // 200 ms stall (GC-like)
    private static final long STALL_EVERY  = 500;       // every 500th call stalls

    private final AtomicLong counter = new AtomicLong();

    // Returns the simulated service time in microseconds for one payment confirm.
    public long confirmPayment(String accountId) {
        long n = counter.incrementAndGet();
        long serviceUs = (n % STALL_EVERY == 0) ? STALL_US : BASELINE_US;
        busyWaitMicros(serviceUs);
        return serviceUs;
    }

    private void busyWaitMicros(long micros) {
        long deadline = System.nanoTime() + micros * 1_000;
        while (System.nanoTime() < deadline) { /* simulate work */ }
    }
}
