package com.bank.loadtest.harness;

import com.bank.loadtest.service.PaymentService;
import org.HdrHistogram.Histogram;

// Closed model: send request, WAIT for response, then send next.
// Records ONLY the measured latency → coordinated omission hides the tail.
public class ClosedModelHarness {
    private final PaymentService service;
    public ClosedModelHarness(PaymentService service) { this.service = service; }

    public Histogram run(int requests) {
        Histogram h = new Histogram(3_600_000_000L, 3); // up to 1 hour in us, 3 sig digits
        for (int i = 0; i < requests; i++) {
            long start = System.nanoTime();
            service.confirmPayment("SAV2001");
            long latencyUs = (System.nanoTime() - start) / 1_000;
            h.recordValue(latencyUs);        // records ONLY what was observed
        }
        return h;
    }
}
