package com.bank.loadtest.harness;

import com.bank.loadtest.service.PaymentService;
import org.HdrHistogram.Histogram;

// Open model: requests are SCHEDULED at a fixed interval regardless of responses.
// Uses recordValueWithExpectedInterval → back-fills omitted samples → true p99.
public class OpenModelHarness {
    private final PaymentService service;
    private final long expectedIntervalUs; // schedule: one request per this interval

    public OpenModelHarness(PaymentService service, long expectedIntervalUs) {
        this.service = service;
        this.expectedIntervalUs = expectedIntervalUs;
    }

    public Histogram run(int requests) {
        Histogram h = new Histogram(3_600_000_000L, 3);
        for (int i = 0; i < requests; i++) {
            long start = System.nanoTime();
            service.confirmPayment("SAV2001");
            long latencyUs = (System.nanoTime() - start) / 1_000;
            // Correction: if this call took longer than the schedule interval,
            // synthesise the latencies of the requests that WOULD have queued.
            h.recordValueWithExpectedInterval(latencyUs, expectedIntervalUs);
        }
        return h;
    }
}
