package com.bank.loadtest;

import com.bank.loadtest.harness.ClosedModelHarness;
import com.bank.loadtest.harness.OpenModelHarness;
import com.bank.loadtest.service.PaymentService;
import java.util.logging.Logger;
import org.HdrHistogram.Histogram;

public class LoadTestDemo {
    private static final Logger log = Logger.getLogger(LoadTestDemo.class.getName());

    public static void main(String[] args) {
        int requests = 50_000;
        long scheduleUs = 100;   // open model expects a request every 100us (10k/s)

        log.info("Running CLOSED model (wait-for-response, JMeter-style)...");
        Histogram closed = new ClosedModelHarness(new PaymentService()).run(requests);

        log.info("Running OPEN model (constant-arrival-rate, wrk2/k6-style)...");
        Histogram open = new OpenModelHarness(new PaymentService(), scheduleUs).run(requests);

        log.info(() -> String.format(
            "CLOSED  median=%.2fms  p99=%.2fms  p99.9=%.2fms  max=%.2fms",
            closed.getValueAtPercentile(50) / 1000.0,
            closed.getValueAtPercentile(99) / 1000.0,
            closed.getValueAtPercentile(99.9) / 1000.0,
            closed.getMaxValue() / 1000.0));

        log.info(() -> String.format(
            "OPEN    median=%.2fms  p99=%.2fms  p99.9=%.2fms  max=%.2fms",
            open.getValueAtPercentile(50) / 1000.0,
            open.getValueAtPercentile(99) / 1000.0,
            open.getValueAtPercentile(99.9) / 1000.0,
            open.getMaxValue() / 1000.0));

        log.warning("The OPEN p99 is the number your customers actually feel.");
    }
}
