package com.bank.loadtest;

import com.bank.loadtest.harness.ClosedModelHarness;
import com.bank.loadtest.harness.OpenModelHarness;
import com.bank.loadtest.service.PaymentService;
import org.HdrHistogram.Histogram;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class CoordinatedOmissionTest {

    @Test
    void openModelReportsHigherTailThanClosedModel() {
        int requests = 20_000;
        Histogram closed = new ClosedModelHarness(new PaymentService()).run(requests);
        Histogram open = new OpenModelHarness(new PaymentService(), 100).run(requests);

        double closedP99 = closed.getValueAtPercentile(99);
        double openP99 = open.getValueAtPercentile(99);

        // The whole point: open-model p99 exposes the hidden tail.
        assertTrue(openP99 > closedP99,
            "open p99 (" + openP99 + ") should exceed closed p99 (" + closedP99 + ")");
    }
}
